<template><div class="page-content"><div class="content-title"><div><h1>页面与内容管理</h1><p>维护页面名称、访问路径、发布状态与组件数量</p></div><button class="primary-btn compact" @click="add">＋ 新建自定义页面</button></div><div class="page-cards"><article v-for="p in config.pages" :key="p.id"><div class="page-visual"><div class="page-mini-head"><i></i><i></i><i></i></div><div v-for="b in p.blocks.slice(0,4)" :key="b.id" :class="['page-mini-block',b.type]"></div></div><div class="page-card-body"><div class="title-row-admin"><div><h3>{{p.name}}</h3><span :class="['status',p.status]">{{p.status==='published'?'已发布':'草稿'}}</span></div><button @click="more===p.id?more=null:more=p.id">···</button></div><p>{{p.path}}</p><div class="page-meta"><span>{{p.blocks.length}} 个组件</span><span>{{p.blocks.filter(b=>b.visible).length}} 个显示</span></div><button class="edit-page" @click="$emit('decorate',p.id)">装修此页面 →</button></div><div v-if="more===p.id" class="more-menu"><button @click="p.status=p.status==='published'?'draft':'published'">{{p.status==='published'?'转为草稿':'立即发布'}}</button><button @click="duplicate(p)">复制页面</button><button class="danger" @click="remove(p)">删除页面</button></div></article></div></div></template>
<script setup>import{ref}from'vue';const props=defineProps({config:Object});const emit=defineEmits(['decorate','toast']);const more=ref(null);const add=()=>{const id=`custom_${Date.now()}`;props.config.pages.push({id,name:'新自定义页面',path:`/pages/custom/${id}`,status:'draft',blocks:[]});emit('toast','自定义页面已创建')};const duplicate=p=>{const n=JSON.parse(JSON.stringify(p));n.id=`${p.id}_copy_${Date.now()}`;n.name+= ' 副本';n.path+=`-copy`;n.status='draft';props.config.pages.push(n);more.value=null;emit('toast','页面已复制')};const remove=p=>{if(props.config.pages.length<=1)return emit('toast','至少保留一个页面');props.config.pages.splice(props.config.pages.indexOf(p),1);more.value=null;emit('toast','页面已删除')}</script>
